{"sql": "WITH valid AS (
  SELECT date_taken, photo_id, subject
  FROM jwst_space_images
  WHERE date_taken >= TIMESTAMP '2022-07-12' AND date_taken <= TIMESTAMP '2026-10-05'
), ordered AS (
  SELECT *, lag(date_taken) OVER (ORDER BY date_taken) AS prev_dt
  FROM valid
), flagged AS (
  SELECT *, CASE WHEN prev_dt IS NULL OR date_diff('millisecond', prev_dt, date_taken) > 168*3600*1000 THEN 1 ELSE 0 END AS is_new
  FROM ordered
), numbered AS (
  SELECT *, sum(is_new) OVER (ORDER BY date_taken) AS burst_id
  FROM flagged
)
SELECT burst_id, min(date_taken) AS s, max(date_taken) AS e, COUNT(*) AS c
FROM numbered GROUP BY burst_id ORDER BY c DESC LIMIT 1"}

{"sql": "SELECT object_name_normalized, COUNT(*) AS n
FROM jwst_space_images
WHERE object_name_normalized IS NOT NULL AND (
 object_name_normalized ILIKE '%pillars%' OR object_name_normalized ILIKE '%eagle%' OR object_name_normalized ILIKE '%M 16%' OR object_name_normalized ILIKE '%NGC 6611%'
)
GROUP BY 1 ORDER BY n DESC"}
